def apply_aggregate(records, aggs, keys):
    if not records:
        return []
    groups={}
    # keys are list of (expr, key_str)
    for rec in records:
        key_vals=[]
        for expr, kstr in keys:
            v,ok,_=eval_expr(expr, rec, emit=False)
            if not ok:
                v=None
            # For grouping, keep value as is (could be None)
            key_vals.append(v)
        kt=tuple(key_vals)
        # Use string representation for dict key if values contain unhashable (like list)? But keys are likely hashable (str, int, datetime, bool, None)
        # For unhashable, convert to str
        try:
            hash(kt)
        except:
            kt=tuple(str(x) for x in key_vals)
        if kt not in groups:
            # init acc
            acc={}
            for agg in aggs:
                if isinstance(agg, CountOp):
                    acc[agg.alias]=0
                elif isinstance(agg, SumOp):
                    acc[agg.alias]=0.0
                elif isinstance(agg, AvgOp):
                    acc[agg.alias+"_sum"]=0.0
                    acc[agg.alias+"_cnt"]=0
                elif isinstance(agg, MinOp):
                    acc[agg.alias]=None
                elif isinstance(agg, MaxOp):
                    acc[agg.alias]=None
                elif isinstance(agg, PercentileOp):
                    acc[agg.alias]=[]
                elif isinstance(agg, CountDistinctOp):
                    acc[agg.alias]=set()
                elif isinstance(agg, TotalOp):
                    acc[agg.alias]=0
                else:
                    pass
            groups[kt]={"key_vals":key_vals, "acc":acc}
        grp=groups[kt]
        acc=grp["acc"]
        for agg in aggs:
            if isinstance(agg, CountOp):
                if agg.cond is None:
                    acc[agg.alias]+=1
                else:
                    cond_val, ok,_=eval_expr(agg.cond, rec, emit=False)
                    if ok and cond_val:
                        # need to handle bool
                        if isinstance(cond_val, bool):
                            if cond_val:
                                acc[agg.alias]+=1
                        else:
                            if cond_val:
                                acc[agg.alias]+=1
            elif isinstance(agg, SumOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    # Check if str is numeric? Already converted
                    acc[agg.alias]+=num
                except:
                    continue
            elif isinstance(agg, AvgOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    acc[agg.alias+"_sum"]+=num
                    acc[agg.alias+"_cnt"]+=1
                except:
                    continue
            elif isinstance(agg, MinOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    cur=acc[agg.alias]
                    if cur is None or num < cur:
                        acc[agg.alias]=num
                except:
                    continue
            elif isinstance(agg, MaxOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    cur=acc[agg.alias]
                    if cur is None or num > cur:
                        acc[agg.alias]=num
                except:
                    continue
            elif isinstance(agg, PercentileOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    acc[agg.alias].append(num)
                except:
                    continue
            elif isinstance(agg, CountDistinctOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok:
                    continue
                # v may be None (explicit null) -> count? But if missing, ok False, we already continued
                acc[agg.alias].add(v)
    result=[]
    for kt, grp in groups.items():
        rec={}
        for (expr,kstr), val in zip(keys, grp["key_vals"]):
            rec[kstr]=val
        acc=grp["acc"]
        for agg in aggs:
            if isinstance(agg, CountOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, SumOp):
                s=acc[agg.alias]
                rec[agg.alias]=s
            elif isinstance(agg, AvgOp):
                s=acc[agg.alias+"_sum"]
                c=acc[agg.alias+"_cnt"]
                if c==0:
                    rec[agg.alias]=None
                else:
                    rec[agg.alias]=s/c
            elif isinstance(agg, MinOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, MaxOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, PercentileOp):
                lst=acc[agg.alias]
                if not lst:
                    rec[agg.alias]=None
                else:
                    lst.sort()
                    N=len(lst)
                    k=math.ceil(agg.p/100 * N)-1
                    if k<0: k=0
                    if k>=N: k=N-1
                    rec[agg.alias]=lst[k]
            elif isinstance(agg, CountDistinctOp):
                rec[agg.alias]=len(acc[agg.alias])
        result.append(rec)
    return result

def apply_sort(records, op):
    # sort using keys
    # Use cmp_to_key for multi-key with asc/desc
    def cmp(a,b):
        for expr, asc, _ in op.keys:
            av, ok1,_=eval_expr(expr, a, emit=False)
            bv, ok2,_=eval_expr(expr, b, emit=False)
            if not ok1:
                av=None
            if not ok2:
                bv=None
            if av is None and bv is None:
                continue
            if av is None:
                return -1 if asc else 1
            if bv is None:
                return 1 if asc else -1
            # both not None
            # if both numbers
            if isinstance(av,(int,float)) and isinstance(bv,(int,float)) and not isinstance(av,bool) and not isinstance(bv,bool):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            if isinstance(av, datetime.datetime) and isinstance(bv, datetime.datetime):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            if isinstance(av, datetime.timedelta) and isinstance(bv, datetime.timedelta):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            # otherwise string compare
            av_s=str(av)
            bv_s=str(bv)
            if av_s < bv_s:
                return -1 if asc else 1
            if av_s > bv_s:
                return 1 if asc else -1
            continue
        return 0
    return sorted(records, key=cmp_to_key(cmp))

