        if a in ('-h','--help'):
            has_help=True
        if a in ('-V','--version'):
            has_version=True
    if has_help:
        # if --help long, else short
        if '--help' in args:
            print(HELP_LONG)
        else:
            print(HELP_SHORT)
        sys.exit(0)
    if has_version:
        print(f"ag {VERSION}")
        sys.exit(0)
    # manual parse
    alias_dir=None
    no_alias=False
    file_path=None
    output="legacy"
    format_str=None
