    while i < len(args):
        a=args[i]
        if a=='--no-alias':
            no_alias=True
            i+=1
        elif a in ('-a','--alias-dir'):
            if i+1 >= len(args):
                eprint("error: --alias-dir requires argument")
                sys.exit(2)
            alias_dir=args[i+1]
            i+=2
        elif a in ('-f','--file'):
            if i+1 >= len(args):
                eprint("error: --file requires argument")
