            file_path=args[i+1]
            i+=2
        elif a in ('-m','--format'):
            if i+1 >= len(args):
                eprint("error: --format requires argument")
                sys.exit(2)
            format_str=args[i+1]
            output="format"
            i+=2
        elif a in ('-o','--output'):
            if i+1 >= len(args):
                eprint("error: --output requires argument")
                sys.exit(2)
            out_val=args[i+1]
            if out_val=="json":
                output="json"
            elif out_val=="logfmt":
                output="logfmt"
            elif out_val=="legacy":
                output="legacy"
            elif out_val.startswith("format="):
                output="format"
                format_str=out_val[len("format="):]
            elif out_val.startswith("format:"):
                output="format"
                format_str=out_val[len("format:"):]
            else:
                # check if contains {
                if "{" in out_val:
                    output="format"
                    format_str=out_val
                else:
                    eprint(f"error: unknown output {out_val}")
                    sys.exit(2)
            i+=2
        elif a.startswith('-'):
            eprint(f"error: unexpected argument '{a}' found")
            sys.exit(2)
        else:
            query=a
            i+=1
            # if remaining args, join as query? but query may contain spaces, but shell would have quoted, so we have single arg
            # However if query was provided without quotes and contains '|', shell would split, but we already split? Actually args parsing with '|' would be separate tokens if not quoted. But query is expected to be single quoted string containing '|'. So we have it.
            # If there are remaining positional args, treat as error? But allow joining
            if i < len(args):
                # combine remaining as part of query (in case of unquoted pipes)
                query = query + " " + " ".join(args[i:])
                break
            break
    if query is None:
        eprint("Error: MissingQuery")
