def eprint(*a, **k):
    print(*a, file=sys.stderr, **k)

def fmt_val(v):
    if v is None:
        return "None"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        if not math.isfinite(v):
            if math.isinf(v):
                return "inf" if v>0 else "-inf"
            return "nan"
        if v.is_integer():
            return str(int(v))
        return f"{v:.2f}"
    if isinstance(v, datetime.datetime):
        if v.tzinfo is None:
            v=v.replace(tzinfo=datetime.timezone.utc)
        base=v.strftime("%Y-%m-%d %H:%M:%S")
        if v.microsecond:
            base+=f".{v.microsecond:06d}"
        return base+" UTC"
    if isinstance(v, datetime.timedelta):
        return str(v)
    if isinstance(v, list):
        return "["+", ".join(fmt_val(x) for x in v)+"]"
    if isinstance(v, dict):
        return json.dumps(v)
    return str(v)

def parse_duration(s):
    m=re.match(r'^(\d+(?:\.\d*)?)(ns|us|ms|s|m|h|d|w)$', s.strip())
    if not m:
        return None
    num=float(m.group(1))
    unit=m.group(2)
    mult={'ns':1e-9,'us':1e-6,'ms':1e-3,'s':1,'m':60,'h':3600,'d':86400,'w':604800}[unit]
    return num*mult

def truncate_dt(dt, secs):
    ts=dt.timestamp()
    trunc=math.floor(ts/secs)*secs
    return datetime.datetime.fromtimestamp(trunc, tz=datetime.timezone.utc)

def parse_date(s):
    s=s.strip()
    fmts=[
        "%Y-%m-%dT%H:%M:%SZ",
        "%Y-%m-%dT%H:%M:%S.%fZ",
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M:%S %Z",
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%Y/%m/%d %H:%M:%S",
        "%d/%b/%Y:%H:%M:%S %z",
        "%a, %d %b %Y %H:%M:%S %Z",
        "%a, %d %b %Y %H:%M:%S GMT",
        "%Y-%m-%dT%H:%M:%S",
    ]
    for fmt in fmts:
        try:
            dt=datetime.datetime.strptime(s, fmt)
            if dt.tzinfo is None:
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except:
            continue
    try:
        dt=datetime.datetime.fromisoformat(s.replace("Z","+00:00"))
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        pass
    try:
        from dateutil import parser as du
        dt=du.parse(s)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        return None

def load_aliases(no_alias, alias_dir):
    aliases={}
    if no_alias:
        return aliases
    dirs=[]
    if alias_dir:
        dirs=[alias_dir]
    else:
        cur=pathlib.Path.cwd()
        while True:
            cand=cur/".agrind-aliases"
            if cand.is_dir():
                dirs.append(str(cand))
            if cur.parent==cur:
                break
            cur=cur.parent
    for d in dirs:
        p=pathlib.Path(d)
        if not p.is_dir():
            continue
        for f in p.glob("*.toml"):
            try:
                txt=f.read_text()
                m=re.search(r'keyword\s*=\s*"([^"]*)"', txt)
                if not m:
                    m=re.search(r"keyword\s*=\s*'([^']*)'", txt)
                kw=m.group(1) if m else None
                tmpl=None
                m=re.search(r'template\s*=\s*"""(.*?)"""', txt, re.S)
                if m:
                    tmpl=m.group(1)
                else:
                    m=re.search(r"template\s*=\s*'''(.*?)'''", txt, re.S)
                    if m:
                        tmpl=m.group(1)
                    else:
                        m=re.search(r'template\s*=\s*"([^"]*)"', txt)
                        if m:
                            tmpl=m.group(1)
                        else:
                            m=re.search(r"template\s*=\s*'([^']*)'", txt)
                            if m:
                                tmpl=m.group(1)
                if kw and tmpl is not None:
                    aliases[kw]=tmpl.strip()
            except:
                pass
    return aliases

def split_query_respecting_quotes(s, delim='|'):
    parts=[]
    cur=""
    in_q=False
    qchar=""
    esc=False
    for ch in s:
        if esc:
            cur+=ch
            esc=False
            continue
        if ch=='\\':
            # keep?
            cur+=ch
            continue
        if in_q:
            if ch==qchar:
                in_q=False
                cur+=ch
            else:
                cur+=ch
        else:
            if ch in ('"',"'"):
                in_q=True
                qchar=ch
                cur+=ch
            elif ch==delim:
                parts.append(cur)
                cur=""
            else:
                cur+=ch
    parts.append(cur)
    return parts

# Filter
def parse_filter_node(s):
    s=s.strip()
    if s=="" or s=="*":
        return None
    class P:
        def __init__(self,t):
            self.t=t
            self.pos=0
            self.n=len(t)
        def skip(self):
            while self.pos<self.n and self.t[self.pos].isspace():
                self.pos+=1
        def parse_or(self):
            node=self.parse_and()
            while True:
                self.skip()
                if self.pos+1<self.n and self.t[self.pos:self.pos+2].upper()=="OR" and (self.pos+2==self.n or not self.t[self.pos+2].isalnum()):
                    self.pos+=2
                    right=self.parse_and()
                    node=("OR",node,right)
                else:
                    break
            return node
        def parse_and(self):
            node=self.parse_not()
            while True:
                self.skip()
                if self.pos+2<self.n and self.t[self.pos:self.pos+3].upper()=="AND" and (self.pos+3==self.n or not self.t[self.pos+3].isalnum()):
                    self.pos+=3
                    right=self.parse_not()
                    node=("AND",node,right)
                    continue
                save=self.pos
                self.skip()
                if self.pos<self.n and self.t[self.pos] not in (')',):
                    if self.pos+1<self.n and self.t[self.pos:self.pos+2].upper()=="OR" and (self.pos+2==self.n or not self.t[self.pos+2].isalnum()):
                        self.pos=save
                        break
                    try:
                        temp=self.pos
                        right=self.parse_not()
                        if right is not None:
                            node=("AND",node,right)
                            continue
                        self.pos=save
                        break
                    except:
                        self.pos=save
                        break
                else:
                    break
            return node
        def parse_not(self):
            self.skip()
            if self.pos+2<self.n and self.t[self.pos:self.pos+3].upper()=="NOT" and (self.pos+3==self.n or self.t[self.pos+3].isspace() or self.t[self.pos+3] in ('(','"',"'")):
                self.pos+=3
                child=self.parse_not()
                return ("NOT",child)
            return self.parse_primary()
        def parse_primary(self):
            self.skip()
            if self.pos>=self.n:
                return None
            ch=self.t[self.pos]
            if ch=='(':
                self.pos+=1
                node=self.parse_or()
                self.skip()
                if self.pos<self.n and self.t[self.pos]==')':
                    self.pos+=1
                return node
            elif ch=='"' or ch=="'":
                q=ch
                self.pos+=1
                buf=""
                while self.pos<self.n:
                    if self.t[self.pos]=='\\' and self.pos+1<self.n:
                        buf+=self.t[self.pos+1]
                        self.pos+=2
                    elif self.t[self.pos]==q:
                        self.pos+=1
                        break
                    else:
                        buf+=self.t[self.pos]
                        self.pos+=1
                return ("TERM",buf,True,False)
            else:
                start=self.pos
                while self.pos<self.n and not self.t[self.pos].isspace() and self.t[self.pos] not in ('(',')','"',"'"):
                    self.pos+=1
                tok=self.t[start:self.pos]
                if tok=="" or tok=="*":
                    return None
                has_wild='*' in tok
                return ("TERM",tok,False,has_wild)
    p=P(s)
    return p.parse_or()

def eval_filter(node, line):
    if node is None:
        return True
    typ=node[0]
    if typ=="TERM":
        _, val, caseSensitive, hasWild=node
        target=line
        pat=val
        if not caseSensitive:
            target=target.lower()
            pat=pat.lower()
        if hasWild:
            regex=re.escape(pat).replace(r"\*",".*")
            return re.search(regex, target) is not None
        else:
            if caseSensitive:
                return val in line
            else:
                return pat in target
    elif typ=="NOT":
        return not eval_filter(node[1], line)
    elif typ=="AND":
        return eval_filter(node[1], line) and eval_filter(node[2], line)
    elif typ=="OR":
        return eval_filter(node[1], line) or eval_filter(node[2], line)
    return False

# Expr parser
class ExprParser:
    def __init__(self, text):
        self.text=text
        self.pos=0
        self.n=len(text)
    def skip(self):
        while self.pos<self.n and self.text[self.pos].isspace():
            self.pos+=1
    def parse_expr(self):
        return self.parse_or()
    def parse_or(self):
        left=self.parse_and()
        while True:
            self.skip()
            save=self.pos
            if self.match_word("or") or self.match_op("||"):
                right=self.parse_and()
                left=("or",left,right)
            else:
                self.pos=save
                break
        return left
    def parse_and(self):
        left=self.parse_comp()
        while True:
            self.skip()
            save=self.pos
            if self.match_word("and") or self.match_op("&&"):
                right=self.parse_comp()
                left=("and",left,right)
            else:
                self.pos=save
                break
        return left
    def match_word(self,w):
        self.skip()
        if self.text[self.pos:self.pos+len(w)].lower()==w.lower():
            after=self.pos+len(w)
            if after<self.n and (self.text[after].isalnum() or self.text[after]=='_'):
                return False
            self.pos+=len(w)
            return True
        return False
    def match_op(self,op):
        self.skip()
        if self.text[self.pos:self.pos+len(op)]==op:
            self.pos+=len(op)
            return True
        return False
    def parse_comp(self):
        left=self.parse_add()
        self.skip()
        for op in ["==","!=","<>","<=",">=","<",">"]:
            if self.text[self.pos:self.pos+len(op)]==op:
                self.pos+=len(op)
                right=self.parse_add()
                return (op,left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while True:
            self.skip()
            if self.pos<self.n and self.text[self.pos] in "+-":
                op=self.text[self.pos]
                self.pos+=1
                right=self.parse_mul()
                left=(op,left,right)
            else:
                break
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while True:
            self.skip()
            if self.pos<self.n and self.text[self.pos] in "*/%":
                op=self.text[self.pos]
                self.pos+=1
                right=self.parse_unary()
                left=(op,left,right)
            else:
                break
        return left
    def parse_unary(self):
        self.skip()
        if self.pos<self.n and self.text[self.pos]=='!':
            self.pos+=1
            e=self.parse_unary()
            return ("not",e)
        if self.pos<self.n and self.text[self.pos]=='-':
            self.pos+=1
            e=self.parse_unary()
            return ("neg",e)
        return self.parse_primary()
    def parse_primary(self):
        self.skip()
        if self.pos>=self.n:
            return None
        ch=self.text[self.pos]
        if ch=='(':
            self.pos+=1
            e=self.parse_expr()
            self.skip()
            if self.pos<self.n and self.text[self.pos]==')':
                self.pos+=1
            return e
        if ch=='"' or ch=="'":
            q=ch
            self.pos+=1
            buf=""
            while self.pos<self.n:
                if self.text[self.pos]=='\\' and self.pos+1<self.n:
                    buf+=self.text[self.pos+1]
                    self.pos+=2
                elif self.text[self.pos]==q:
                    self.pos+=1
                    break
                else:
                    buf+=self.text[self.pos]
                    self.pos+=1
            return ("str",buf)
        m=re.match(r'-?\d+(?:\.\d*)?(?:[eE][+-]?\d+)?', self.text[self.pos:])
        if m:
            s=m.group(0)
            self.pos+=len(s)
            if '.' in s or 'e' in s.lower():
                return ("num", float(s))
            else:
                return ("num", int(s))
        if ch.isalpha() or ch=='_' or ch=='[':
            return self.parse_field_or_func()
        self.pos+=1
        return ("str",ch)
    def parse_field_or_func(self):
        self.skip()
        if self.pos<self.n and self.text[self.pos]=='[':
            if self.pos+1<self.n and self.text[self.pos+1]=='"':
                self.pos+=1
                self.pos+=1
                buf=""
                while self.pos<self.n:
                    if self.text[self.pos]=='\\' and self.pos+1<self.n:
                        buf+=self.text[self.pos+1]; self.pos+=2
                    elif self.text[self.pos]=='"':
                        self.pos+=1; break
                    else:
                        buf+=self.text[self.pos]; self.pos+=1
                self.skip()
                if self.pos<self.n and self.text[self.pos]==']':
                    self.pos+=1
                full=("field",buf)
                full=self.parse_field_cont(full)
                self.skip()
                if self.pos<self.n and self.text[self.pos]=='(' and full[0]=='field':
                    func=full[1]
                    self.pos+=1
                    args=[]
                    self.skip()
                    if self.pos<self.n and self.text[self.pos]==')':
                        self.pos+=1
                        return ("call",func,args)
                    while True:
                        args.append(self.parse_expr())
                        self.skip()
                        if self.pos<self.n and self.text[self.pos]==',':
                            self.pos+=1; continue
                        if self.pos<self.n and self.text[self.pos]==')':
                            self.pos+=1; break
                        break
                    return ("call",func,args)
                return full
        start=self.pos
        while self.pos<self.n and (self.text[self.pos].isalnum() or self.text[self.pos]=='_'):
            self.pos+=1
        name=self.text[start:self.pos]
        if not name:
            return None
        full=("field",name)
        full=self.parse_field_cont(full)
        self.skip()
        if self.pos<self.n and self.text[self.pos]=='(':
            if full[0]=='field' and len(full)==2:
                func=full[1]
                self.pos+=1
                args=[]
                self.skip()
                if self.pos<self.n and self.text[self.pos]==')':
                    self.pos+=1
                    return ("call",func,args)
                while True:
                    args.append(self.parse_expr())
                    self.skip()
                    if self.pos<self.n and self.text[self.pos]==',':
                        self.pos+=1; continue
                    if self.pos<self.n and self.text[self.pos]==')':
                        self.pos+=1; break
                    break
                return ("call",func,args)
        low=name.lower()
        if low=="true":
            return ("bool",True)
        if low=="false":
            return ("bool",False)
        if low=="null" or low=="none":
            return ("null",None)
        return full
    def parse_field_cont(self, full):
        while True:
            self.skip()
            if self.pos<self.n and self.text[self.pos]=='.':
                self.pos+=1
                self.skip()
                if self.pos<self.n and self.text[self.pos]=='[':
                    self.pos+=1
                    self.skip()
                    if self.pos<self.n and self.text[self.pos] in ('"',"'"):
                        q=self.text[self.pos]; self.pos+=1
                        buf=""
                        while self.pos<self.n and self.text[self.pos]!=q:
                            if self.text[self.pos]=='\\' and self.pos+1<self.n:
                                buf+=self.text[self.pos+1]; self.pos+=2
                            else:
                                buf+=self.text[self.pos]; self.pos+=1
                        if self.pos<self.n and self.text[self.pos]==q:
                            self.pos+=1
                        self.skip()
                        if self.pos<self.n and self.text[self.pos]==']':
                            self.pos+=1
                        full=("field_bracket_str",full,buf)
                    else:
                        s=self.pos
                        if self.pos<self.n and self.text[self.pos]=='-':
                            self.pos+=1
                        while self.pos<self.n and self.text[self.pos].isdigit():
                            self.pos+=1
                        idx_str=self.text[s:self.pos]
                        self.skip()
                        if self.pos<self.n and self.text[self.pos]==']':
                            self.pos+=1
                        try:
                            idx=int(idx_str)
                        except:
                            idx=0
                        full=("field_index",full,idx)
                else:
                    s=self.pos
                    while self.pos<self.n and (self.text[self.pos].isalnum() or self.text[self.pos]=='_'):
                        self.pos+=1
                    sub=self.text[s:self.pos]
                    if sub:
                        full=("field_dot",full,sub)
                    else:
                        break
            elif self.pos<self.n and self.text[self.pos]=='[':
                self.pos+=1
                self.skip()
                if self.pos<self.n and self.text[self.pos] in ('"',"'"):
                    q=self.text[self.pos]; self.pos+=1
                    buf=""
                    while self.pos<self.n and self.text[self.pos]!=q:
                        if self.text[self.pos]=='\\' and self.pos+1<self.n:
                            buf+=self.text[self.pos+1]; self.pos+=2
                        else:
                            buf+=self.text[self.pos]; self.pos+=1
                    if self.pos<self.n and self.text[self.pos]==q:
                        self.pos+=1
                    self.skip()
                    if self.pos<self.n and self.text[self.pos]==']':
                        self.pos+=1
                    full=("field_bracket_str",full,buf)
                else:
                    s=self.pos
                    if self.pos<self.n and self.text[self.pos]=='-':
                        self.pos+=1
                    while self.pos<self.n and self.text[self.pos].isdigit():
                        self.pos+=1
                    idx_str=self.text[s:self.pos]
                    if self.pos<self.n and self.text[self.pos]==']':
                        self.pos+=1
                    try:
                        idx=int(idx_str)
                    except:
                        idx=0
                    full=("field_index",full,idx)
            else:
                break
        return full

def parse_expr(s):
    p=ExprParser(s)
    return p.parse_expr()

def get_field(record, node):
    if node[0]=="field":
        k=node[1]
        if k in record:
            return record[k], True
        return None, False
    elif node[0]=="field_dot":
        pv,ok=get_field(record, node[1])
        if not ok:
            return None, False
        sub=node[2]
        if isinstance(pv, dict):
            if sub in pv:
                return pv[sub], True
            return None, False
        return None, False
    elif node[0]=="field_index":
        pv,ok=get_field(record, node[1])
        if not ok:
            return None, False
        idx=node[2]
        if isinstance(pv, list):
            try:
                if idx<0:
                    idx=len(pv)+idx
                return pv[idx], True
            except:
                return None, False
        return None, False
    elif node[0]=="field_bracket_str":
        pv,ok=get_field(record, node[1])
        sub=node[2]
        if isinstance(pv, dict):
            if sub in pv:
                return pv[sub], True
            return None, False
        return None, False
    return None, False

def eval_expr(node, record, emit=True):
    if node is None:
        return None, False, "missing"
    typ=node[0]
    if typ=="num":
        return node[1], True, None
    if typ=="str":
        return node[1], True, None
    if typ=="bool":
        return node[1], True, None
    if typ=="null":
        return None, True, None
    if typ in ("field","field_dot","field_index","field_bracket_str"):
        v,ok=get_field(record, node)
        if not ok:
            if emit:
                def fname(n):
                    if n[0]=="field":
                        return n[1]
                    elif n[0]=="field_dot":
                        return fname(n[1])+"."+n[2]
                    elif n[0]=="field_index":
                        return fname(n[1])+f"[{n[2]}]"
                    elif n[0]=="field_bracket_str":
                        return fname(n[1])+f'["{n[2]}"]'
                    return str(n)
                eprint(f'error: No value for key "{fname(node)}"')
            return None, False, "missing"
        return v, True, None
    if typ=="call":
        func=node[1]
        args=node[2]
        evaled=[]
        for a in args:
            v,ok,_=eval_expr(a, record, emit)
            if not ok:
                evaled.append(None)
            else:
                evaled.append(v)
        low=func.lower()
        try:
            if low=="abs":
                if evaled[0] is None: return None, False, "null"
                return abs(float(evaled[0])), True, None
            if low in ("acos","asin","atan","cos","sin","tan","cosh","sinh","tanh","exp","log","log10","sqrt","cbrt","ceil","floor","round","expm1","log1p"):
                v=float(evaled[0])
                import math as m
                if low=="acos": return m.acos(v), True, None
                if low=="asin": return m.asin(v), True, None
                if low=="atan": return m.atan(v), True, None
                if low=="cos": return m.cos(v), True, None
                if low=="sin": return m.sin(v), True, None
                if low=="tan": return m.tan(v), True, None
                if low=="cosh": return m.cosh(v), True, None
                if low=="sinh": return m.sinh(v), True, None
                if low=="tanh": return m.tanh(v), True, None
                if low=="exp": return m.exp(v), True, None
                if low=="log": return m.log(v), True, None
                if low=="log10": return m.log10(v), True, None
                if low=="sqrt": return m.sqrt(v), True, None
                if low=="cbrt": return (v**(1/3)) if v>=0 else -((-v)**(1/3)), True, None
                if low=="ceil": return m.ceil(v), True, None
                if low=="floor": return m.floor(v), True, None
                if low=="round": return round(v), True, None
                if low=="expm1": return m.expm1(v), True, None
                if low=="log1p": return m.log1p(v), True, None
            if low=="atan2":
                return math.atan2(float(evaled[0]), float(evaled[1])), True, None
            if low=="hypot":
                return math.hypot(float(evaled[0]), float(evaled[1])), True, None
            if low=="todegrees":
                return math.degrees(float(evaled[0])), True, None
            if low=="toradians":
                return math.radians(float(evaled[0])), True, None
            if low=="concat":
                return "".join(str(x) if x is not None else "" for x in evaled), True, None
            if low=="contains":
                hay=str(evaled[0]) if evaled[0] is not None else ""
                needle=str(evaled[1]) if evaled[1] is not None else ""
                return needle in hay, True, None
            if low=="length":
                if isinstance(evaled[0], list):
                    return len(evaled[0]), True, None
                s=str(evaled[0]) if evaled[0] is not None else ""
                return len(s), True, None
            if low=="now":
                return datetime.datetime.now(datetime.timezone.utc), True, None
            if low=="num":
                s=evaled[0]
                if s is None:
                    eprint(f"error: Expected number, found {s}")
                    return None, False, "num"
                try:
                    if isinstance(s,(int,float)):
                        return float(s), True, None
                    str_s=str(s).strip()
                    if re.match(r'^-?\d+$', str_s):
                        return int(str_s), True, None
                    return float(str_s), True, None
                except:
                    eprint(f"error: Expected number, found {s}")
                    return None, False, "num"
            if low=="parsedate":
                s=str(evaled[0])
                dt=parse_date(s)
                if dt is None:
                    eprint(f"error: The 'parseDate' function failed with the error: UnrecognizedToken(\":\")")
                    return None, False, "parsedate"
                return dt, True, None
            if low=="parsehex":
                s=str(evaled[0])
                try:
                    sc=s.strip()
                    if sc.lower().startswith("0x"):
                        sc=sc[2:]
                    return int(sc,16), True, None
                except:
                    eprint(f"error: The 'parseHex' function failed with the error: invalid hex string -- {s}")
                    return None, False, "parsehex"
            if low=="substring":
                s=str(evaled[0]) if evaled[0] is not None else ""
                start=int(float(evaled[1])) if len(evaled)>1 and evaled[1] is not None else 0
                if len(evaled)>2 and evaled[2] is not None:
                    end=int(float(evaled[2]))
                    return s[start:end], True, None
                else:
                    return s[start:], True, None
            if low=="tolowercase":
                return str(evaled[0]).lower(), True, None
            if low=="touppercase":
                return str(evaled[0]).upper(), True, None
            if low=="isnull":
                return evaled[0] is None, True, None
            if low=="isempty":
                v=evaled[0]
                return v is None or (isinstance(v,str) and v==""), True, None
            if low=="isblank":
                v=evaled[0]
                return v is None or (isinstance(v,str) and v.strip()==""), True, None
            if low=="isnumeric":
                v=evaled[0]
                if v is None:
                    return False, True, None
                try:
                    float(str(v))
                    return True, True, None
                except:
                    return False, True, None
            if low=="if":
                cond=evaled[0]
                is_true=False
                if isinstance(cond,bool):
                    is_true=cond
                elif cond is None:
                    is_true=False
                else:
                    is_true=bool(cond)
                if is_true:
                    return evaled[1], True, None
                else:
                    if len(evaled)>=3:
                        return evaled[2], True, None
                    return None, True, None
            eprint(f"error: Unknown function {func}")
            return None, False, "unknown"
        except Exception as e:
            eprint(f"error: Function {func} failed: {e}")
            return None, False, str(e)
    if typ=="not":
        v,ok,_=eval_expr(node[1], record, emit)
        if not ok:
            return None, False, "missing"
        return (not bool(v)), True, None
    if typ=="neg":
        v,ok,_=eval_expr(node[1], record, emit)
        if not ok:
            return None, False, "missing"
        try:
            return -float(v), True, None
        except:
            return None, False, "neg"
    if typ in ("+","-","*","/","%"):
        l,ok1,_=eval_expr(node[1], record, emit)
        r,ok2,_=eval_expr(node[2], record, emit)
        if not ok1 or not ok2:
            return None, False, "missing"
        try:
            if isinstance(l, datetime.datetime) and isinstance(r, datetime.timedelta):
                if typ=="+":
                    return l+r, True, None
                if typ=="-":
                    return l-r, True, None
            if isinstance(l, datetime.datetime) and isinstance(r, datetime.datetime) and typ=="-":
                return l-r, True, None
            def to_num(x):
                if isinstance(x,(int,float)) and not isinstance(x,bool):
                    return x
                if isinstance(x,str):
                    try:
                        if '.' in x or 'e' in x.lower():
                            return float(x)
                        return int(x)
                    except:
                        return None
                return None
            ln=to_num(l)
            rn=to_num(r)
            if ln is not None and rn is not None:
                if typ=="+":
                    return ln+rn, True, None
                if typ=="-":
                    return ln-rn, True, None
                if typ=="*":
                    return ln*rn, True, None
                if typ=="/":
                    if rn==0:
                        return float('inf') if ln>0 else float('-inf') if ln<0 else float('nan'), True, None
                    return ln/rn, True, None
                if typ=="%":
                    return ln%rn, True, None
            if typ=="+":
                return str(l)+str(r), True, None
            return None, False, "type"
        except Exception as e:
            return None, False, str(e)
    if typ in ("==","!=","<>","<",">","<=",">="):
        l,ok1,_=eval_expr(node[1], record, False)
        r,ok2,_=eval_expr(node[2], record, False)
        if not ok1 and not ok2:
            if typ=="==":
                return True, True, None
            if typ in ("!=","<>"):
                return False, True, None
            return False, True, None
        if not ok1 or not ok2:
            if typ=="==":
                return (l==r), True, None
            if typ in ("!=","<>"):
                return (l!=r), True, None
            return False, True, None
        def try_num(x):
            if isinstance(x,(int,float)) and not isinstance(x,bool):
                return x
            if isinstance(x,str):
                try:
                    if '.' in x or 'e' in x.lower():
                        return float(x)
                    return int(x)
                except:
                    return None
            return None
        ln=try_num(l)
        rn=try_num(r)
        if typ=="==":
            if l==r:
                return True, True, None
            if ln is not None and rn is not None and ln==rn:
                return True, True, None
            return str(l)==str(r), True, None
        if typ in ("!=","<>"):
            if l==r:
                return False, True, None
            if ln is not None and rn is not None and ln==rn:
                return False, True, None
            return str(l)!=str(r), True, None
        if isinstance(l,(int,float)) and isinstance(r,(int,float)) and not isinstance(l,bool) and not isinstance(r,bool):
            lv=l; rv=r
        elif isinstance(l, datetime.datetime) and isinstance(r, datetime.datetime):
            lv=l; rv=r
        elif isinstance(l, datetime.timedelta) and isinstance(r, datetime.timedelta):
            lv=l; rv=r
        else:
            lv=str(l); rv=str(r)
        if typ=="<":
            return lv<rv, True, None
        if typ==">":
            return lv>rv, True, None
        if typ=="<=":
            return lv<=rv, True, None
        if typ==">=":
            return lv>=rv, True, None
    if typ in ("and","or"):
        l,ok1,_=eval_expr(node[1], record, emit)
        if typ=="and":
            if not bool(l):
                return False, True, None
            r,ok2,_=eval_expr(node[2], record, emit)
            return bool(r), True, None
        else:
            if bool(l):
                return True, True, None
            r,ok2,_=eval_expr(node[2], record, emit)
            return bool(r), True, None
    return None, False, "unknown"

# Ops
class JsonOp:
    def __init__(self, frm=None): self.frm=frm
class LogfmtOp:
    def __init__(self, frm=None): self.frm=frm
class SplitOp:
    def __init__(self, inp=None, sep=",", new="_split"): self.inp=inp; self.sep=sep; self.new=new
class ParseOp:
    def __init__(self, pat, frm=None, fields=None, nodrop=False, noconvert=False, is_regex=False):
        self.pat=pat; self.frm=frm; self.fields=fields; self.nodrop=nodrop; self.noconvert=noconvert; self.is_regex=is_regex
class FieldsOp:
    def __init__(self, mode, fields): self.mode=mode; self.fields=fields
class WhereOp:
    def __init__(self, expr): self.expr=expr
class LimitOp:
    def __init__(self, n): self.n=n
class ExprAsOp:
    def __init__(self, expr, alias): self.expr=expr; self.alias=alias
class CountOp:
    def __init__(self, cond=None, alias="_count"): self.cond=cond; self.alias=alias
class SumOp:
    def __init__(self, field, alias="_sum"): self.field=field; self.alias=alias
class AvgOp:
    def __init__(self, field, alias="_average"): self.field=field; self.alias=alias
class MinOp:
    def __init__(self, field, alias="_min"): self.field=field; self.alias=alias
class MaxOp:
    def __init__(self, field, alias="_max"): self.field=field; self.alias=alias
class PercentileOp:
    def __init__(self, p, field, alias=None): self.p=p; self.field=field; self.alias=alias if alias else f"p{p}"
class CountDistinctOp:
    def __init__(self, field, alias="_countDistinct"): self.field=field; self.alias=alias
class SortOp:
    def __init__(self, keys): self.keys=keys
class TimesliceOp:
    def __init__(self, expr, dur_str, alias="_timeslice"):
        self.expr=expr; self.dur_str=dur_str; self.alias=alias; self.secs=parse_duration(dur_str)
class TotalOp:
    def __init__(self, field, alias="_total"): self.field=field; self.alias=alias
class AggGroup:
    def __init__(self, aggs, keys):
        self.aggs=aggs
        self.keys=keys

def parse_operator(s):
    s_stripped=s.strip()
    low=s_stripped.lower()
    m=re.match(r'^json(?:\s+from\s+(\S+))?\s*$', s_stripped, re.I)
    if m:
        return JsonOp(m.group(1))
    m=re.match(r'^logfmt(?:\s+from\s+(\S+))?\s*$', s_stripped, re.I)
    if m:
        return LogfmtOp(m.group(1))
    if low.startswith("split"):
        rest=s_stripped[5:].strip()
        inp=None
        sep=","
        new="_split"
        if rest.startswith("("):
            idx=rest.find(")")
            if idx!=-1:
                inner=rest[1:idx].strip()
                if inner:
                    inp=inner
                rest=rest[idx+1:].strip()
        m_on=re.search(r'\bon\s+("(?:\\.|[^"])*"|\'(?:\\.|[^\'])*\'|\S+)\s*', rest, re.I)
        if m_on:
            raw=m_on.group(1)
            if (raw.startswith('"') and raw.endswith('"')) or (raw.startswith("'") and raw.endswith("'")):
                sep=raw[1:-1].replace('\\"', '"').replace("\\'", "'")
            else:
                sep=raw
            rest=rest[:m_on.start()]+rest[m_on.end():]
            rest=rest.strip()
        m_as=re.search(r'\bas\s+(\S+)\s*$', rest, re.I)
        if m_as:
            new=m_as.group(1)
            rest=rest[:m_as.start()].strip()
        else:
            if inp is not None:
                new=inp
        return SplitOp(inp, sep, new)
    if low.startswith("parse"):
        if re.match(r'^parse\s+regex\s+', s_stripped, re.I):
            m=re.match(r'^parse\s+regex\s+(".*?"|\'.*?\'|\S+)\s*(.*)$', s_stripped, re.I|re.S)
            if not m:
                eprint("error: Failed to parse parse regex")
                sys.exit(1)
            pat_raw=m.group(1)
            rest=m.group(2).strip()
            pat=pat_raw[1:-1] if (pat_raw.startswith('"') or pat_raw.startswith("'")) else pat_raw
            frm=None
            nodrop=False
            m_from=re.search(r'\bfrom\s+(\S+)', rest, re.I)
            if m_from:
                frm=m_from.group(1)
                rest=rest[:m_from.start()]+rest[m_from.end():]
                rest=rest.strip()
            if re.search(r'\bnodrop\b', rest, re.I):
                nodrop=True
            return ParseOp(pat, frm, None, nodrop, False, True)
        else:
            m=re.match(r'^parse\s+(".*?"|\'.*?\'|[^ ]+)\s*(.*)$', s_stripped, re.S)
            if not m:
                return None
            pat_raw=m.group(1)
            rest=m.group(2)
            if not pat_raw:
                return None
            if (pat_raw.startswith('"') and pat_raw.endswith('"')) or (pat_raw.startswith("'") and pat_raw.endswith("'")):
                pat=pat_raw[1:-1]
            else:
                pat=pat_raw
            frm=None
            fields=None
            nodrop=False
            noconvert=False
            m_as=re.search(r'\bas\s+(.+)$', rest, re.I|re.S)
            as_part=None
            before_as=rest
            if m_as:
                as_part=m_as.group(1).strip()
                before_as=rest[:m_as.start()].strip()
                temp=as_part
                if re.search(r'\bnoconvert\b', temp, re.I):
                    noconvert=True
                    temp=re.sub(r'\bnoconvert\b','',temp, flags=re.I).strip()
                if re.search(r'\bnodrop\b', temp, re.I):
                    nodrop=True
                    temp=re.sub(r'\bnodrop\b','',temp, flags=re.I).strip()
                fields=[f.strip() for f in temp.split(',') if f.strip()!='']
                if not fields:
                    fields=None
            if before_as:
                m_from=re.search(r'\bfrom\s+(\S+)', before_as, re.I)
                if m_from:
                    frm=m_from.group(1)
                    before_as=before_as[:m_from.start()]+before_as[m_from.end():]
                    before_as=before_as.strip()
                if re.search(r'\bnodrop\b', before_as, re.I):
                    nodrop=True
                if re.search(r'\bnoconvert\b', before_as, re.I):
                    noconvert=True
            if fields is None:
                return None
            return ParseOp(pat, frm, fields, nodrop, noconvert, False)
    if low.startswith("fields"):
        rest=s_stripped[6:].strip()
        if not rest:
            eprint(f"error: expecting an operand for binary operator\n  |\n1 | {s_stripped}\n  |                     - dangling binary operator\n  |\n  = help: Add the operand or delete the operator\nError: Failed to parse query")
            sys.exit(1)
        m=re.match(r'^([+\-]|only|except)\s+(.*)$', rest, re.I)
        if m:
            mode=m.group(1).lower()
            if mode=='+': mode='only'
            elif mode=='-': mode='except'
            fields_str=m.group(2)
            fields=[f.strip() for f in fields_str.split(',') if f.strip()!='']
        else:
            mode='only'
            fields=[f.strip() for f in rest.split(',') if f.strip()!='']
        norm=[]
        for f in fields:
            f=f.strip()
            if f.startswith('["') and f.endswith('"]'):
                norm.append(f[2:-2])
            elif f.startswith("['") and f.endswith("']"):
                norm.append(f[2:-2])
            else:
                if (f.startswith('"') and f.endswith('"')) or (f.startswith("'") and f.endswith("'")):
                    norm.append(f[1:-1])
                else:
                    # handle ["a b"] without quotes? already
                    m2=re.match(r'^\["(.*)"\]$', f)
                    if m2:
                        norm.append(m2.group(1))
                    else:
                        norm.append(f)
        return FieldsOp(mode, norm)
    if low.startswith("where"):
        rest=s_stripped[5:].strip()
        if not rest:
            eprint(f"error: Expected an expression\n  |\n1 | {s_stripped}\n  |            ^^^^^ No condition provided for this 'where'\n  |\n  = help: Insert an expression whose result determines whether a record should be passed downstream\n  = help: example: where duration > 100\nError: Expected an expression")
            sys.exit(1)
        expr_node=parse_expr(rest)
        if expr_node and expr_node[0]=="str":
            eprint(f'error: Expected boolean expression, found Str("{expr_node[1]}")\n  |\n1 | {s_stripped}\n  |           {"^"*len(rest)} This is constant\n  |\n  = help: Perhaps you meant to compare a field to this value?\n  = help: example: where field1 == {expr_node[1]}\nError: Expected boolean expression, found Str("{expr_node[1]}")')
            sys.exit(1)
        return WhereOp(expr_node)
    if low.startswith("limit"):
        rest=s_stripped[5:].strip()
        if not rest:
            eprint("error: Failed to parse limit")
            sys.exit(1)
        try:
            n=int(rest.split()[0])
        except:
            eprint("error: Failed to parse limit")
            sys.exit(1)
        if n==0:
            eprint(f"error: Limit must be a non-zero integer, found 0\n  |\n1 | {s_stripped}\n  |           ^ Zero is not allowed\n  |\n  = help: Use a positive integer to select the first N rows\n  = help: Use a negative integer to select the last N rows\nError: Limit must be a non-zero integer, found 0")
            sys.exit(1)
        return LimitOp(n)
    if low.startswith("sort"):
        m=re.match(r'^sort\s+by\s+(.*)$', s_stripped, re.I)
        if not m:
            eprint("error: Failed to parse sort")
            sys.exit(1)
        keys_str=m.group(1).strip()
        parts=[]
        cur=""; depth=0; in_q=False; qch=""
        for ch in keys_str:
            if in_q:
                if ch==qch: in_q=False
                cur+=ch
            else:
                if ch in ('"',"'"): in_q=True; qch=ch; cur+=ch
                elif ch=='(' or ch=='[': depth+=1; cur+=ch
                elif ch==')' or ch==']': depth-=1; cur+=ch
                elif ch==',' and depth==0: parts.append(cur.strip()); cur=""
                else: cur+=ch
        if cur.strip(): parts.append(cur.strip())
        keys=[]
        for part in parts:
            m2=re.match(r'^(.*)\s+(asc|desc)\s*$', part, re.I)
            if m2:
                expr_str=m2.group(1).strip()
                asc=m2.group(2).lower()=="asc"
            else:
                expr_str=part
                asc=True
            expr_node=parse_expr(expr_str)
            keys.append((expr_node, asc, expr_str))
        return SortOp(keys)
    if low.startswith("timeslice"):
        m=re.match(r'^timeslice\s*\(\s*(.+?)\s*\)\s+(\S+)(?:\s+as\s+(\S+))?\s*$', s_stripped, re.I)
        if not m:
            eprint("error: Failed to parse timeslice")
            sys.exit(1)
        expr_str=m.group(1).strip()
        dur_str=m.group(2).strip()
        alias=m.group(3) if m.group(3) else "_timeslice"
        expr_node=parse_expr(expr_str)
        return TimesliceOp(expr_node, dur_str, alias)
    if low.startswith("total"):
        if re.search(r'\bby\b', s_stripped, re.I):
            eprint(f"error: unrecognized option, only the 'as' option is available\n  |\n1 | {s_stripped}\n  |                     ^^^^\n  |\nError: Failed to parse query")
            sys.exit(1)
        m=re.match(r'^total\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', s_stripped, re.I)
        if not m:
            eprint("error: Failed to parse total")
            sys.exit(1)
        field_str=m.group(1).strip()
        alias=m.group(2) if m.group(2) else "_total"
        expr_node=parse_expr(field_str)
        return TotalOp(expr_node, alias)
    has_by=bool(re.search(r'\bby\b', s_stripped, re.I))
    is_agg=False
    if has_by:
        is_agg=True
    else:
        for kw in ["count","sum","average","avg","min","max","count_distinct"]:
            if re.match(r'^'+kw+r'\b', s_stripped, re.I):
                is_agg=True
                break
        if re.match(r'^p\d+\b', s_stripped, re.I):
            is_agg=True
    if is_agg:
        return parse_aggregate_segment(s_stripped)
    if re.search(r'\bas\b', s_stripped, re.I):
        m=re.search(r'^(.*)\bas\b\s*(\S+)\s*$', s_stripped, re.I)
        if m:
            expr_str=m.group(1).strip()
            alias=m.group(2).strip()
            if alias.startswith('["') and alias.endswith('"]'):
                alias=alias[2:-2]
            elif alias.startswith("['") and alias.endswith("']"):
                alias=alias[2:-2]
            elif (alias.startswith('"') and alias.endswith('"')) or (alias.startswith("'") and alias.endswith("'")):
                alias=alias[1:-1]
            expr_node=parse_expr(expr_str)
            return ExprAsOp(expr_node, alias)
    return None

def parse_aggregate_segment(s):
    m_by=re.search(r'\bby\b', s, re.I)
    aggs_part=s
    keys_part=None
    if m_by:
        aggs_part=s[:m_by.start()].strip()
        keys_part=s[m_by.end():].strip()
    else:
        aggs_part=s.strip()
        keys_part=None
    def split_aggs(txt):
        parts=[]; cur=""; depth=0; in_q=False; qch=""
        for ch in txt:
            if in_q:
                if ch==qch: in_q=False
                cur+=ch
            else:
                if ch in ('"',"'"): in_q=True; qch=ch; cur+=ch
                elif ch=='(': depth+=1; cur+=ch
                elif ch==')': depth-=1; cur+=ch
                elif ch==',' and depth==0: parts.append(cur.strip()); cur=""
                else: cur+=ch
        if cur.strip(): parts.append(cur.strip())
        return parts
    if not aggs_part.strip():
        aggs_strs=[]
    else:
        aggs_strs=split_aggs(aggs_part)
    ops=[]
    for agg_s in aggs_strs:
        agg_s=agg_s.strip()
        if not agg_s:
            continue
        low=agg_s.lower()
        m=re.match(r'^count(?:\s*\(\s*(.*?)\s*\))?(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m and (low.startswith("count") and not low.startswith("count_distinct")):
            cond_str=m.group(1)
            alias=m.group(2) if m.group(2) else "_count"
            if alias and alias.startswith('["'):
                if alias.startswith('["') and alias.endswith('"]'):
                    alias=alias[2:-2]
            cond_node=None
            if cond_str is not None and cond_str.strip()!="":
                cond_node=parse_expr(cond_str.strip())
            ops.append(CountOp(cond_node, alias))
            continue
        m=re.match(r'^sum\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            field_str=m.group(1).strip()
            alias=m.group(2) if m.group(2) else "_sum"
            if not field_str:
                eprint(f"error: this operator takes 1 argument, but 0 were supplied\n  |\n1 | {s}\n  |                 - supplied 0 arguments\n  |\n  = help: the argument should supply the numeric value to find the sum of\nError: Failed to parse query")
                sys.exit(1)
            expr_node=parse_expr(field_str)
            ops.append(SumOp(expr_node, alias))
            continue
        m=re.match(r'^average\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_average"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(AvgOp(expr_node, alias))
            continue
        m=re.match(r'^avg\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_average"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(AvgOp(expr_node, alias))
            continue
        m=re.match(r'^min\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_min"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(MinOp(expr_node, alias))
            continue
        m=re.match(r'^max\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_max"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(MaxOp(expr_node, alias))
            continue
        m=re.match(r'^p(\d+)\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            p=int(m.group(1))
            alias=m.group(3) if m.group(3) else f"p{p}"
            expr_node=parse_expr(m.group(2).strip())
            ops.append(PercentileOp(p, expr_node, alias))
            continue
        m=re.match(r'^count_distinct\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_countDistinct"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(CountDistinctOp(expr_node, alias))
            continue
        m=re.match(r'^total\s*\(\s*(.+?)\s*\)(?:\s+as\s+(\S+))?\s*$', agg_s, re.I)
        if m:
            alias=m.group(2) if m.group(2) else "_total"
            expr_node=parse_expr(m.group(1).strip())
            ops.append(TotalOp(expr_node, alias))
            continue
        eprint(f"error: Failed to parse aggregate '{agg_s}'")
        sys.exit(1)
    if keys_part is not None:
        def split_keys(txt):
            parts=[]; cur=""; depth=0; in_q=False; qch=""
            for ch in txt:
                if in_q:
                    if ch==qch: in_q=False
                    cur+=ch
                else:
                    if ch in ('"',"'"): in_q=True; qch=ch; cur+=ch
                    elif ch in ('(','['): depth+=1; cur+=ch
                    elif ch in (')',']'): depth-=1; cur+=ch
                    elif ch==',' and depth==0: parts.append(cur.strip()); cur=""
                    else: cur+=ch
            if cur.strip(): parts.append(cur.strip())
            return parts
        key_strs=split_keys(keys_part)
        keys=[]
        for ks in key_strs:
            ks=ks.strip()
            if not ks:
                continue
            expr_node=parse_expr(ks)
            keys.append((expr_node, ks))
        if ops:
            return AggGroup(ops, keys)
        else:
            eprint("error: Failed to parse aggregate")
            sys.exit(1)
    else:
        if len(ops)==1:
            return ops[0]
        elif len(ops)>1:
            return AggGroup(ops, [])
        else:
            return None

def parse_query(query_str, aliases):
    expanded=query_str
    for _ in range(5):
        parts=split_query_respecting_quotes(expanded, '|')
        new_parts=[]
        changed=False
        for seg in parts:
            seg_s=seg.strip()
            if seg_s in aliases:
                tmpl=aliases[seg_s]
                tmpl_parts=split_query_respecting_quotes(tmpl, '|')
                new_parts.extend([p.strip() for p in tmpl_parts])
                changed=True
            else:
                new_parts.append(seg)
        expanded=" | ".join(new_parts)
        if not changed:
            break
    query_str=expanded
    parts=split_query_respecting_quotes(query_str, '|')
    parts=[p.strip() for p in parts]
    if not parts:
        return None, []
    filter_str=parts[0]
    op_strs=parts[1:]
    filter_node=None
    if filter_str.strip() not in ("", "*"):
        filter_node=parse_filter_node(filter_str)
    elif filter_str.strip()=="*":
        filter_node=None
    else:
        filter_node=None
    operators=[]
    for op_s in op_strs:
        if not op_s.strip():
            continue
        op=parse_operator(op_s)
        if op is None:
            known=["json","logfmt","split","parse","fields","where","limit","sort","timeslice","total","count","sum","average","avg","min","max","count_distinct"]
            first_word=re.match(r'^\s*(\w+)', op_s)
            if first_word:
                w=first_word.group(1).lower()
                if w not in known and not re.match(r'^p\d+', w):
                    eprint(f"error: Expected an operator\n  |\n1 | {query_str}\n  |     {op_s}\n  |\n  = help: {w} is not a valid operator\nError: Failed to parse query")
                    sys.exit(1)
                else:
                    continue
            else:
                eprint(f"error: Expected an operator\n  |\n1 | {query_str}\n  |     {op_s}\n  |\n  = help: {op_s} is not a valid operator\nError: Failed to parse query")
                sys.exit(1)
        if isinstance(op, list):
            operators.extend(op)
        else:
            operators.append(op)
    return filter_node, operators

def apply_operators(records, operators):
    cur_records=records
    has_agg=False
    for op in operators:
        if isinstance(op, (JsonOp, LogfmtOp, SplitOp, ParseOp, FieldsOp, WhereOp, LimitOp, ExprAsOp, TimesliceOp, TotalOp)):
            cur_records=apply_non_agg(cur_records, op)
        elif isinstance(op, (CountOp, SumOp, AvgOp, MinOp, MaxOp, PercentileOp, CountDistinctOp)):
            cur_records=apply_aggregate(cur_records, [op], [])
            has_agg=True
        elif isinstance(op, AggGroup):
            cur_records=apply_aggregate(cur_records, op.aggs, op.keys)
            has_agg=True
        elif isinstance(op, SortOp):
            cur_records=apply_sort(cur_records, op)
            # sort is considered aggregate for output? Keep has_agg True if we already had aggregate, else need to consider sort after non-agg? For sort after non-aggregate? But sort only makes sense after aggregate.
            # We'll mark has_agg True because sort output is table-like
            # Check if cur_records was previously aggregate -> keep, else if sort on non-aggregate? Not typical
            # We'll set has_agg True if we think output is aggregated
            # For now, if sort follows aggregate, has_agg already True, else we need to decide
            # We'll set has_agg = True if cur_records is not empty and has keys that look like aggregate? Simplify: set True
            has_agg=True
        else:
            eprint(f"unknown operator {op}")
            sys.exit(1)
    return cur_records, has_agg

def apply_non_agg(records, op):
    out=[]
    if isinstance(op, JsonOp):
        for rec in records:
            src=rec["_raw"] if op.frm is None else rec.get(op.frm, "")
            if src is None:
                src=""
            src=str(src)
            try:
                obj=json.loads(src)
                new_rec=rec.copy()
                if isinstance(obj, dict):
                    for k,v in obj.items():
                        new_rec[k]=v
                out.append(new_rec)
            except Exception as e:
                eprint(f"error: Expected JSON, found {src}")
                continue
        return out
    if isinstance(op, LogfmtOp):
        for rec in records:
            src=rec["_raw"] if op.frm is None else rec.get(op.frm, "")
            if src is None:
                src=""
            src=str(src)
            new_rec=rec.copy()
            pairs=re.findall(r'(\w+)=("[^"]*"|\'[^\']*\'|\S+)', src)
            if pairs:
                for k,v in pairs:
                    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                        v=v[1:-1]
                    new_rec[k]=v
            else:
                tokens=src.split()
                for tok in tokens:
                    if '=' in tok:
                        k,v=tok.split('=',1)
                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                            v=v[1:-1]
                        new_rec[k]=v
                    else:
                        if tok:
                            new_rec[tok]=None
            out.append(new_rec)
        return out
    if isinstance(op, SplitOp):
        for rec in records:
            src=None
            if op.inp is None:
                src=rec.get("_raw","")
            else:
                src=rec.get(op.inp)
                if src is None:
                    eprint(f'error: No value for key "{op.inp}"')
                    continue
            src=str(src)
            parts=src.split(op.sep)
            new_rec=rec.copy()
            new_rec[op.new]=parts
            out.append(new_rec)
        return out
    if isinstance(op, ParseOp):
        for rec in records:
            src=rec["_raw"] if op.frm is None else rec.get(op.frm, "")
            if src is None:
                src=""
            src=str(src)
            matched=False
            groups=None
            groupdict=None
            if op.is_regex:
                try:
                    m=re.search(op.pat, src)
                    if m:
                        gd=m.groupdict()
                        if gd:
                            groups=list(gd.values())
                            groupdict=gd
                            matched=True
                        else:
                            groups=list(m.groups())
                            matched=True if groups else False
                            if not groups:
                                # if no groups but matched, consider matched
                                matched=True
                    else:
                        matched=False
                except re.error as e:
                    eprint(f"error: Invalid regex {op.pat}: {e}")
                    matched=False
            else:
                pat=op.pat
                regex="^"
                i=0
                n=len(pat)
                while i<n:
                    ch=pat[i]
                    if ch=='*':
                        regex+="(.*?)"
                        i+=1
                    elif ch.isspace():
                        regex+=r"\s+"
                        while i<n and pat[i].isspace():
                            i+=1
                    else:
                        regex+=re.escape(ch)
                        i+=1
                regex+="$"
                try:
                    m=re.match(regex, src, re.DOTALL)
                    if m:
                        groups=m.groups()
                        matched=True
                    else:
                        matched=False
                except re.error as e:
                    eprint(f"error: Invalid pattern {pat}: {e}")
                    matched=False
            if matched:
                new_rec=rec.copy()
                if op.is_regex:
                    if groupdict:
                        for k,v in groupdict.items():
                            if v is not None and not op.noconvert:
                                if re.match(r'^-?\d+$', v):
                                    try: v=int(v)
                                    except: pass
                                elif re.match(r'^-?\d*\.\d+(?:[eE][+-]?\d+)?$', v):
                                    try: v=float(v)
                                    except: pass
                            new_rec[k]=v
                else:
                    if op.fields:
                        for idx, field_name in enumerate(op.fields):
                            if idx < len(groups):
                                v=groups[idx]
                                if v is not None and not op.noconvert:
                                    v_str=v.strip() if isinstance(v,str) else str(v)
                                    if re.match(r'^-?\d+$', v_str):
                                        try: v=int(v_str)
                                        except: pass
                                    elif re.match(r'^-?\d*\.\d+(?:[eE][+-]?\d+)?$', v_str):
                                        try: v=float(v_str)
                                        except: pass
                                    else:
                                        v=v_str
                                new_rec[field_name]=v
                            else:
                                new_rec[field_name]=None
                out.append(new_rec)
            else:
                if op.nodrop:
                    new_rec=rec.copy()
                    if not op.is_regex and op.fields:
                        for f in op.fields:
                            new_rec[f]=None
                    elif op.is_regex:
                        names=re.findall(r'\(\?P<(\w+)>', op.pat)
                        for n in names:
                            new_rec[n]=None
                    out.append(new_rec)
                else:
                    continue
        return out
    if isinstance(op, FieldsOp):
        for rec in records:
            new_rec={}
            if op.mode=='only':
                for f in op.fields:
                    if f in rec:
                        new_rec[f]=rec[f]
            elif op.mode=='except':
                new_rec=rec.copy()
                for f in op.fields:
                    new_rec.pop(f, None)
            else:
                new_rec=rec.copy()
            out.append(new_rec)
        return out
    if isinstance(op, WhereOp):
        for rec in records:
            v,ok,_=eval_expr(op.expr, rec, emit=True)
            if ok and v:
                out.append(rec)
            else:
                continue
        return out
    if isinstance(op, LimitOp):
        n=op.n
        if n>0:
            return records[:n]
        else:
            return records[n:]
    if isinstance(op, ExprAsOp):
        for rec in records:
            v,ok,_=eval_expr(op.expr, rec, emit=True)
            if not ok:
                continue
            new_rec=rec.copy()
            new_rec[op.alias]=v
            out.append(new_rec)
        return out
    if isinstance(op, TimesliceOp):
        for rec in records:
            v,ok,_=eval_expr(op.expr, rec, emit=True)
            if not ok or v is None:
                continue
            dt=None
            if isinstance(v, datetime.datetime):
                dt=v
            else:
                try:
                    dt=parse_date(str(v))
                except:
                    dt=None
            if dt is None or op.secs is None:
                continue
            trunc=truncate_dt(dt, op.secs)
            new_rec=rec.copy()
            new_rec[op.alias]=trunc
            out.append(new_rec)
        return out
    if isinstance(op, TotalOp):
        total=0
        for rec in records:
            v,ok,_=eval_expr(op.field, rec, emit=False)
            if ok and v is not None and not isinstance(v,bool):
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    total+=num
                except:
                    pass
            new_rec=rec.copy()
            new_rec[op.alias]=total
            out.append(new_rec)
        return out
    return records

def apply_aggregate(records, aggs, keys):
    if not records:
        return []
    groups={}
    for rec in records:
        key_vals=[]
        for expr, kstr in keys:
            v,ok,_=eval_expr(expr, rec, emit=False)
            if not ok:
                v=None
            key_vals.append(v)
        kt=tuple(key_vals)
        try:
            hash(kt)
        except:
            kt=tuple(str(x) for x in key_vals)
        if kt not in groups:
            acc={}
            for agg in aggs:
                if isinstance(agg, CountOp):
                    acc[agg.alias]=0
                elif isinstance(agg, SumOp):
                    acc[agg.alias]=0.0
                elif isinstance(agg, AvgOp):
                    acc[agg.alias+"_sum"]=0.0
                    acc[agg.alias+"_cnt"]=0
                elif isinstance(agg, MinOp):
                    acc[agg.alias]=None
                elif isinstance(agg, MaxOp):
                    acc[agg.alias]=None
                elif isinstance(agg, PercentileOp):
                    acc[agg.alias]=[]
                elif isinstance(agg, CountDistinctOp):
                    acc[agg.alias]=set()
                elif isinstance(agg, TotalOp):
                    acc[agg.alias]=0
            groups[kt]={"key_vals":key_vals, "acc":acc}
        grp=groups[kt]
        acc=grp["acc"]
        for agg in aggs:
            if isinstance(agg, CountOp):
                if agg.cond is None:
                    acc[agg.alias]+=1
                else:
                    cond_val, ok,_=eval_expr(agg.cond, rec, emit=False)
                    if ok and cond_val:
                        if isinstance(cond_val,bool):
                            if cond_val:
                                acc[agg.alias]+=1
                        elif cond_val:
                            acc[agg.alias]+=1
            elif isinstance(agg, SumOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    acc[agg.alias]+=num
                except:
                    continue
            elif isinstance(agg, AvgOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    acc[agg.alias+"_sum"]+=num
                    acc[agg.alias+"_cnt"]+=1
                except:
                    continue
            elif isinstance(agg, MinOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    cur=acc[agg.alias]
                    if cur is None or num < cur:
                        acc[agg.alias]=num
                except:
                    continue
            elif isinstance(agg, MaxOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    cur=acc[agg.alias]
                    if cur is None or num > cur:
                        acc[agg.alias]=num
                except:
                    continue
            elif isinstance(agg, PercentileOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok or v is None or isinstance(v,bool):
                    continue
                try:
                    if isinstance(v,str):
                        num=float(v)
                    else:
                        num=float(v)
                    acc[agg.alias].append(num)
                except:
                    continue
            elif isinstance(agg, CountDistinctOp):
                v,ok,_=eval_expr(agg.field, rec, emit=False)
                if not ok:
                    continue
                acc[agg.alias].add(v)
    result=[]
    for kt, grp in groups.items():
        rec={}
        for (expr,kstr), val in zip(keys, grp["key_vals"]):
            rec[kstr]=val
        acc=grp["acc"]
        for agg in aggs:
            if isinstance(agg, CountOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, SumOp):
                s=acc[agg.alias]
                rec[agg.alias]=s
            elif isinstance(agg, AvgOp):
                s=acc[agg.alias+"_sum"]
                c=acc[agg.alias+"_cnt"]
                rec[agg.alias]=s/c if c!=0 else None
            elif isinstance(agg, MinOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, MaxOp):
                rec[agg.alias]=acc[agg.alias]
            elif isinstance(agg, PercentileOp):
                lst=acc[agg.alias]
                if not lst:
                    rec[agg.alias]=None
                else:
                    lst.sort()
                    N=len(lst)
                    k=math.ceil(agg.p/100 * N)-1
                    if k<0: k=0
                    if k>=N: k=N-1
                    rec[agg.alias]=lst[k]
            elif isinstance(agg, CountDistinctOp):
                rec[agg.alias]=len(acc[agg.alias])
        result.append(rec)
    return result

def apply_sort(records, op):
    def cmp(a,b):
        for expr, asc, _ in op.keys:
            av, ok1,_=eval_expr(expr, a, emit=False)
            bv, ok2,_=eval_expr(expr, b, emit=False)
            if not ok1:
                av=None
            if not ok2:
                bv=None
            if av is None and bv is None:
                continue
            if av is None:
                return -1 if asc else 1
            if bv is None:
                return 1 if asc else -1
            if isinstance(av,(int,float)) and isinstance(bv,(int,float)) and not isinstance(av,bool) and not isinstance(bv,bool):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            if isinstance(av, datetime.datetime) and isinstance(bv, datetime.datetime):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            if isinstance(av, datetime.timedelta) and isinstance(bv, datetime.timedelta):
                if av < bv:
                    return -1 if asc else 1
                if av > bv:
                    return 1 if asc else -1
                continue
            av_s=str(av); bv_s=str(bv)
            if av_s < bv_s:
                return -1 if asc else 1
            if av_s > bv_s:
                return 1 if asc else -1
            continue
        return 0
    return sorted(records, key=cmp_to_key(cmp))

def main():
    args=sys.argv[1:]
    has_help=False
    has_version=False
    for a in args:
        if a in ('-h','--help'):
            has_help=True
        if a in ('-V','--version'):
            has_version=True
    if has_help:
        if '--help' in args:
            print(HELP_LONG)
        else:
            print(HELP_SHORT)
        sys.exit(0)
    if has_version:
        print(f"ag {VERSION}")
        sys.exit(0)
    alias_dir=None
    no_alias=False
    file_path=None
    output="legacy"
    format_str=None
    query=None
    i=0
    while i < len(args):
        a=args[i]
        if a=='--no-alias':
            no_alias=True
            i+=1
        elif a in ('-a','--alias-dir'):
            if i+1 >= len(args):
                eprint("error: --alias-dir requires argument")
                sys.exit(2)
            alias_dir=args[i+1]
            i+=2
        elif a in ('-f','--file'):
            if i+1 >= len(args):
                eprint("error: --file requires argument")
                sys.exit(2)
            file_path=args[i+1]
            i+=2
        elif a in ('-m','--format'):
            if i+1 >= len(args):
                eprint("error: --format requires argument")
                sys.exit(2)
            format_str=args[i+1]
            output="format"
            i+=2
        elif a in ('-o','--output'):
            if i+1 >= len(args):
                eprint("error: --output requires argument")
                sys.exit(2)
            out_val=args[i+1]
            if out_val=="json":
                output="json"
            elif out_val=="logfmt":
                output="logfmt"
            elif out_val=="legacy":
                output="legacy"
            elif out_val.startswith("format="):
                output="format"
                format_str=out_val[len("format="):]
            elif out_val.startswith("format:"):
                output="format"
                format_str=out_val[len("format:"):]
            else:
                if "{" in out_val:
                    output="format"
                    format_str=out_val
                else:
                    eprint(f"error: unknown output {out_val}")
                    sys.exit(2)
            i+=2
        elif a.startswith('-'):
            eprint(f"error: unexpected argument '{a}' found")
            sys.exit(2)
        else:
            query=a
            i+=1
            if i < len(args):
                query = query + " " + " ".join(args[i:])
                break
            break
    if query is None:
        eprint("Error: MissingQuery")
        sys.exit(1)
    aliases=load_aliases(no_alias, alias_dir)
    filter_node, operators=parse_query(query, aliases)
    lines=[]
    if file_path:
        try:
            with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
                lines=f.read().splitlines()
        except Exception as e:
            eprint(f"Error: {e}")
            sys.exit(1)
    else:
        data=sys.stdin.read().splitlines()
        lines=data
    filtered=[]
    for line in lines:
        if not eval_filter(filter_node, line):
            continue
        filtered.append({"_raw": line})
    cur_records, has_agg = apply_operators(filtered, operators)
    if not cur_records:
        if has_agg:
            if output=="json":
                print("[]")
                sys.exit(0)
            elif output=="logfmt":
                sys.exit(0)
            elif output=="format":
                sys.exit(0)
            else:
                print("No data")
                sys.exit(0)
        else:
            sys.exit(0)
    if output=="json":
        if has_agg:
            jlist=[]
            for rec in cur_records:
                jrec={}
                for k,v in rec.items():
                    if isinstance(v, datetime.datetime):
                        jrec[k]=fmt_val(v)
                    elif isinstance(v, datetime.timedelta):
                        jrec[k]=str(v)
                    elif isinstance(v, float):
                        jrec[k]=v
                    else:
                        jrec[k]=v
                jlist.append(jrec)
            print(json.dumps(jlist, separators=(',',':')))
        else:
            for rec in cur_records:
                out_rec={}
                for k,v in rec.items():
                    if k=="_raw":
                        continue
                    if isinstance(v, datetime.datetime):
                        out_rec[k]=fmt_val(v)
                    elif isinstance(v, datetime.timedelta):
                        out_rec[k]=str(v)
                    else:
                        out_rec[k]=v
                print(json.dumps(out_rec, separators=(',',':')))
        sys.exit(0)
    elif output=="logfmt":
        if has_agg:
            for rec in cur_records:
                parts=[]
                for k in sorted(rec.keys()):
                    v=rec[k]
                    if v is None:
                        vs="None"
                    elif isinstance(v,bool):
                        vs="true" if v else "false"
                    elif isinstance(v,(int,float)):
                        vs=fmt_val(v)
                    elif isinstance(v, datetime.datetime):
                        vs=fmt_val(v)
                    elif isinstance(v, list):
                        vs=fmt_val(v)
                    else:
                        vs=str(v)
                    parts.append(f"{k}={vs}")
                print(" ".join(parts))
        else:
            for rec in cur_records:
                parts=[]
                for k in sorted(rec.keys()):
                    if k=="_raw":
                        continue
                    v=rec[k]
                    if v is None:
                        vs="None"
                    elif isinstance(v,bool):
                        vs="true" if v else "false"
                    elif isinstance(v,(int,float)):
                        vs=fmt_val(v)
                    elif isinstance(v, datetime.datetime):
                        vs=fmt_val(v)
                    elif isinstance(v, list):
                        vs=fmt_val(v)
                    else:
                        vs=str(v)
                    parts.append(f"{k}={vs}")
                print(" ".join(parts))
        sys.exit(0)
    elif output=="format":
        fmt=format_str if format_str is not None else ""
        for rec in cur_records:
            def repl(m):
                inner=m.group(1)
                if ':' in inner:
                    key, fmt_spec=inner.split(':',1)
                else:
                    key=inner
                    fmt_spec=None
                v=rec.get(key)
                if v is None:
                    vs="None"
                else:
                    vs=fmt_val(v)
                if fmt_spec:
                    try:
                        vs=format(vs, fmt_spec)
                    except:
                        pass
                return vs
            out_line=re.sub(r'\{([^}]+)\}', repl, fmt)
            print(out_line)
        sys.exit(0)
    else: # legacy
        if has_agg:
            # Determine headers order
            headers=list(cur_records[0].keys())
            # Find if we had explicit sort: if operators contains SortOp, we already sorted; otherwise apply default sort
            has_sort=any(isinstance(op, SortOp) for op in operators)
            if not has_sort:
                # default sort by first agg descending
                aggs_in_order=[]
                for op in operators:
                    if isinstance(op, AggGroup):
                        aggs_in_order.extend([a.alias for a in op.aggs])
                    elif isinstance(op, (CountOp, SumOp, AvgOp, MinOp, MaxOp, PercentileOp, CountDistinctOp)):
                        aggs_in_order.append(op.alias)
                if aggs_in_order:
                    first=aggs_in_order[0]
                    def cmp_agg(a,b):
                        av=a.get(first)
                        bv=b.get(first)
                        try:
                            anv=float(av) if av is not None else float('-inf')
                            bnv=float(bv) if bv is not None else float('-inf')
                            if anv != bnv:
                                return -1 if anv > bnv else 1
                        except:
                            avs=str(av); bvs=str(bv)
                            if avs != bvs:
                                return -1 if avs > bvs else 1
                        for k in headers:
                            if k in aggs_in_order:
                                continue
                            aks=str(a.get(k)); bks=str(b.get(k))
                            if aks != bks:
                                return -1 if aks < bks else 1
                        return 0
                    cur_records=sorted(cur_records, key=cmp_to_key(cmp_agg))
            # compute widths
            widths=[]
            for h in headers:
                max_len=len(h)
                for rec in cur_records:
                    v=rec.get(h)
                    vs=fmt_val(v)
                    if len(vs) > max_len:
                        max_len=len(vs)
                widths.append(max_len)
            header_line="        ".join(h.ljust(w) for h,w in zip(headers,widths))
            # Trim trailing spaces for last column? The header_line already has last column padded, but original header line pads last column to width (which may be extra spaces?). For y _count example, _count is last column width6, header "_count" length6, so no extra. For superlong case, _count still last, no extra. So header_line as we built is correct (last column padded to width but width == len(header) exactly, so no extra). But our join adds 8 spaces between, not after last, so fine.
            print(header_line)
            print("-"*(len(header_line)+8))
            for rec in cur_records:
                parts=[]
                for h,w in zip(headers,widths):
                    v=rec.get(h)
                    vs=fmt_val(v)
                    parts.append(vs.ljust(w))
                print("        ".join(parts))
        else:
            # non-aggregate legacy: sort keys alphabetically, join with 8 spaces, no global alignment (per row)
            for rec in cur_records:
                keys_sorted=sorted(k for k in rec.keys() if k!="_raw")
                parts=[]
                for k in keys_sorted:
                    v=rec[k]
                    vs=fmt_val(v)
                    parts.append(f"[{k}={vs}]")
                # Join with 8 spaces
                print("        ".join(parts))
        sys.exit(0)

